      .hero-details { display: block; margin: 25px 0 28px; }
      .intro { max-width: 280px; font-size: 18px; }
      .primary { margin-top: 24px; min-height: 52px; gap: 33px; padding-inline: 18px; }
      .film { aspect-ratio: 1.16; }
      .film-control { right: 12px; bottom: 12px; }
      .work { display: block; padding-block: 48px; }
