    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      *, *::before, *::after { transition: none "'!important; }
    }
  </style>
</head>
<body>
  <div class="page">
    <header class="site-header">
      <div class="brand">FIELD NOTES</div>
      <nav aria-label="Main navigation">
        <a href="#work">Work</a>
        <a href="#about">About</a>
        <a href="mailto:studio@example.test">Contact</a>
      </nav>
    </header>
    <main>
      <section class="hero" aria-labelledby="hero-heading">
        <h1 id="hero-heading"><span>Make room for</span> <span>the moving world.</span></h1>
        <div class="hero-details">
          <p class="intro">Thoughtful films, clear stories, lasting places.</p>
          <a class="primary" href="#work">Explore the work<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M12 3v17m-6-6 6 6 6-6"/></svg></a>
        </div>
        <div class="film">
          <video muted loop playsinline preload="none" poster="assets/poster.svg" aria-hidden="true" tabindex="-1">
            <source src="assets/scene.webm" type="video/webm">
          </video>
          <button class="film-control" type="button" aria-label="Play film" data-playing="false" hidden>
            <svg class="play" viewBox="0 0 24 24" aria-hidden="true"><path d="m8 4 13 8-13 8z"/></svg>
            <svg class="pause" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h4v16H6zm8 0h4v16h-4z"/></svg>
          </button>
        </div>
      </section>
      <section class="work" id="work" aria-labelledby="work-heading">
        <h2 id="work-heading">Selected work</h2>
        <ul class="work-list">
          <li>Tidal study / 2026</li>
          <li>Mountain light / 2025</li>
        </ul>
      </section>
      <section class="about" id="about" aria-label="About">
        <p>An independent film practice.</p>
      </section>
    </main>
  </div>
  <script>
    (() => {
      const video = document.querySelector('"'video');
      const control = document.querySelector('.film-control');
      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
      let userPaused = false;
      let failed = false;
      let inView = true;
      const syncControl = () => {
        const playing = "'!video.paused;
        control.dataset.playing = String(playing);
        control.setAttribute('"'aria-label', playing ? 'Pause film' : 'Play film');
      };
      const play = () => {
        if (failed) return;
        const attempt = video.play();
        if (attempt) attempt.catch(syncControl);
      };
      const settlePlayback = () => {
        if (document.hidden || "'!inView || reducedMotion.matches || userPaused) video.pause();
        else play();
      };
      control.hidden = false;
      control.addEventListener('"'click', () => {
        if (video.paused) { userPaused = false; play(); }
        else { userPaused = true; video.pause(); }
      });
      video.addEventListener('play', syncControl);
      video.addEventListener('pause', syncControl);
      const showPoster = () => {
        failed = true;
        video.pause();
        video.hidden = true;
        video.style.display = 'none';
        control.hidden = true;
      };
      video.addEventListener('error', showPoster);
      video.querySelector('source').addEventListener('error', showPoster);
      document.addEventListener('visibilitychange', settlePlayback);
      if (reducedMotion.addEventListener) reducedMotion.addEventListener('change', settlePlayback);
      else if (reducedMotion.addListener) reducedMotion.addListener(settlePlayback);
      if ('IntersectionObserver' in window) {
        new IntersectionObserver(([entry]) => {
          inView = entry.isIntersecting;
          settlePlayback();
        }, { threshold: 0 }).observe(video);
      }
      settlePlayback();
    })();
  </script>
</body>
</html>
EOF
