for (const asset of ['assets/scene.webm', 'assets/poster.svg']) assert(fs.existsSync(asset) && html.includes(asset), asset);
assert(html.includes('id=\"work\"') && html.includes('id=\"about\"'));
assert("'!/(?:src|href)="https?:'"\\/\\//.test(html));
console.log('PASS: inline JavaScript syntax, required copy, exact destinations, section IDs, and local media references.');
console.log('Browser/runtime behavior: unverified.');
